('fundamentals','control','Which action is a security control?','single','[{"id":"a","label":"Restrict access to authorised staff"},{"id":"b","label":"Record orders in a spreadsheet"}]',1),
('cia-check','availability','Fictional scenario: A shop cannot retrieve its booking list. Is availability affected?','boolean','[{"id":"true","label":"True"},{"id":"false","label":"False"}]',1),
('chapter-check','disclosure','Fictional scenario: A former employee can still see customer bookings. Which objective is most directly affected?','single','[{"id":"c","label":"Confidentiality"},{"id":"i","label":"Integrity"},{"id":"a","label":"Availability"}]',1),
('chapter-check','controls','Fictional scenario: Which actions support recovery after losing access to the booking calendar?','multiple','[{"id":"backup","label":"Keep backups"},{"id":"restore","label":"Test restoring a backup"},{"id":"rename","label":"Rename the calendar"}]',2);

